    #[test]
    #[cfg(feature = "zeroize")]
    fn test_index_map_zeroize() {
        use zeroize::Zeroize;

        let mut map: FnvIndexMap<u8, u8, 8> = FnvIndexMap::new();
        for i in 1..=8 {
            map.insert(i, i * 10).unwrap();
        }

        assert_eq!(map.len(), 8);
        assert!(!map.is_empty());

        // zeroized using Vec's implementation
        map.zeroize();

        assert_eq!(map.len(), 0);
        assert!(map.is_empty());

        map.insert(1, 10).unwrap();
        assert_eq!(map.len(), 1);
        assert_eq!(map.get(&1), Some(&10));
    }

    #[test]
    fn test_use_after_free_clear() {
        // See https://github.com/rust-embedded/heapless/issues/646

        static COUNT: AtomicI32 = AtomicI32::new(0);

        #[derive(Debug, Hash, PartialEq, Eq)]
        #[allow(unused)]
        struct Dropper();

        impl Dropper {
            fn new() -> Self {
                COUNT.fetch_add(1, Ordering::Relaxed);
                Self()
            }
            fn count() -> i32 {
                COUNT.load(Ordering::Relaxed)
            }
        }
        impl Drop for Dropper {
            fn drop(&mut self) {
                COUNT.fetch_sub(1, Ordering::Relaxed);
                panic!("Testing  panicking");
            }
        }

        let mut history_buf = FnvIndexMap::<Dropper, u32, 8>::new();
        history_buf.insert(Dropper::new(), 0).unwrap();
        // Don't panic on dropping of the history_buf
        let mut history_buf = ManuallyDrop::new(history_buf);
        let mut unwind_safe_history_buf = AssertUnwindSafe(&mut history_buf);

        catch_unwind(move || unwind_safe_history_buf.clear()).unwrap_err();
        assert_eq!(history_buf.len(), 0);
        history_buf.clear();
        assert_eq!(Dropper::count(), 0);
    }

    /// See <https://github.com/rust-embedded/heapless/issues/674>
    #[test]
    fn truncate_invalid() {
        let mut map: FnvIndexMap<u16, u32, 4> = FnvIndexMap::new();
        map.insert(4, 444).unwrap();
        map.insert(2, 222).unwrap();
        map.insert(0, 0).unwrap();
        map.insert(7, 7).unwrap();

        assert_eq!(map.get(&2), Some(&222)); // ok before map.truncate(2);
        map.truncate(2);
        assert_eq!(map.iter().collect::<Vec<_>>(), vec![(&4, &444), (&2, &222)]); // ok
        assert_eq!(map.get(&4), Some(&444)); // ok
        assert_eq!(map.get(&2), Some(&222)); // <-- key present in iter() but unreachable
    }
}
